"""matplotlib.backends.backend_gtk3agg — gtk3agg backend stub.

The shim renders every figure through plotly, so this module exists to
satisfy ``from matplotlib.backends.backend_gtk3agg import
FigureCanvasGTK3Agg`` imports. Saving uses plotly's native export.
"""

from matplotlib.backends._backend_helpers import (
    _make_canvas, _make_manager, _make_backend,
)


FigureCanvasGTK3Agg = _make_canvas('FigureCanvasGTK3Agg', 'png')
FigureManagerGTK3Agg = _make_manager('FigureManagerGTK3Agg')

# Aliases — every backend exposes ``FigureCanvas`` and ``FigureManager``.
FigureCanvas = FigureCanvasGTK3Agg
FigureManager = FigureManagerGTK3Agg

# Backend class registered with matplotlib's _Backend system.
_BackendStub = _make_backend('_BackendGTK3Agg', FigureCanvas, FigureManager)
new_figure_manager = _BackendStub.new_figure_manager
draw_if_interactive = _BackendStub.draw_if_interactive
show = _BackendStub.show
